'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const KEY='commonplace.press.v1',TOPICS=['Science','Biology','History','Technology','Parenting','Habits','Learning','Courage','Friendship','Life & meaning','Love','Inspiration','Humor','Philosophy','God','Wisdom','Romance','Truth','Poetry','Life lessons','Death','Happiness','Hope','Faith','Relationships','Spirituality','Motivation','Religion','Writing','Success','Time','Politics','Art','Nature'];
const ICONS=['✳','❧','⌛','⌘','♧','↻','◈','✧','❦','☼'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const number=n=>Number(n).toLocaleString('en-US');
let state={selected:[],favorites:[],custom:[],ratings:{},shelf:[],book:{title:'Commonplace Book',author:'',format:'5x8',theme:'forest',sources:true}},library=[],topic='All topics',section='',age='all',collection='all',page=1,toastTimer,saveOkay=true,catalogClient=null,manifest=null,querySerial=0,recordCache=new Map(),archiveAuthors=new Set(),storageBlocked=false,unreadableSavedState=null;
function validPopularity(p){return p===undefined||p===null||p&&p.source==='Goodreads'&&typeof p.sourceUrl==='string'&&p.sourceUrl.length<=1000&&typeof p.snapshotDate==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(p.snapshotDate)&&(p.likes===null||Number.isInteger(p.likes)&&p.likes>=0&&p.likes<=100000000)}
function validateQuote(q){return q&&typeof q.id==='string'&&q.id.length<200&&typeof q.text==='string'&&q.text.trim().length>0&&q.text.length<=3000&&typeof q.author==='string'&&q.author.trim().length>0&&q.author.length<=150&&Array.isArray(q.topics)&&q.topics.length<=64&&q.topics.every(t=>TOPICS.includes(t))&&Number.isInteger(q.minAge)&&q.minAge>=0&&q.minAge<=18&&Number.isInteger(q.importance)&&q.importance>=1&&q.importance<=5&&(q.year===null||Number.isInteger(q.year)&&q.year>=-3000&&q.year<=2026)&&(q.likes===null||Number.isInteger(q.likes)&&q.likes>=0&&q.likes<=100000000)&&typeof q.source==='string'&&q.source.length<=250&&typeof q.sourceUrl==='string'&&q.sourceUrl.length<=1000&&validPopularity(q.popularity)&&CommonplaceDates.valid(q.chronology)}
function validBook(b){return b&&typeof b.title==='string'&&b.title.trim().length>0&&b.title.length<=80&&typeof b.author==='string'&&b.author.length<=80&&(b.dedication===undefined||typeof b.dedication==='string'&&b.dedication.length<=200)&&['6x9','5x8','a5'].includes(b.format)&&Object.hasOwn(CommonplaceCover.themes,b.theme)&&typeof b.sources==='boolean'&&(b.titleFont===undefined||Object.hasOwn(CommonplaceCover.fonts,b.titleFont))&&(b.titleSize===undefined||Number.isFinite(b.titleSize)&&b.titleSize>=12&&b.titleSize<=40)&&(b.coverColor===undefined||b.coverColor===null||/^#[0-9a-f]{6}$/i.test(b.coverColor))&&(b.coverImage===undefined||b.coverImage===null||typeof b.coverImage==='string'&&b.coverImage.length<=1500000&&/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(b.coverImage))&&(b.pad===undefined||typeof b.pad==='boolean')&&(b.spine===undefined||b.spine===null||typeof b.spine==='number'&&Number.isFinite(b.spine)&&b.spine>=0&&b.spine<=5)}
function validateState(s){return s&&Array.isArray(s.custom)&&s.custom.length<=10000&&s.custom.every(validateQuote)&&new Set(s.custom.map(q=>q.id)).size===s.custom.length&&s.custom.every(q=>q.id.startsWith('own-'))&&Array.isArray(s.selected)&&s.selected.length<=2000&&s.selected.every(x=>typeof x==='string')&&Array.isArray(s.favorites)&&s.favorites.length<=20000&&s.favorites.every(x=>typeof x==='string')&&validBook(s.book)&&Array.isArray(s.shelf)&&s.shelf.length<=200&&s.shelf.every(e=>e&&typeof e.id==='string'&&typeof e.date==='string'&&validBook(e.book)&&Array.isArray(e.selected)&&e.selected.length<=2000&&e.selected.every(x=>typeof x==='string'))&&(s.records===undefined||s.records&&typeof s.records==='object'&&!Array.isArray(s.records)&&Object.keys(s.records).length<=100000&&Object.entries(s.records).every(([id,q])=>id===q.id&&validateQuote(q)))&&s.ratings&&typeof s.ratings==='object'&&!Array.isArray(s.ratings)&&Object.entries(s.ratings).every(([k,v])=>k!=='__proto__'&&Number.isInteger(v)&&v>=1&&v<=5)}
try{unreadableSavedState=localStorage.getItem(KEY);if(unreadableSavedState){const saved=JSON.parse(unreadableSavedState);if(validateState(saved)){state=saved;state.records=state.records||{};unreadableSavedState=null}else{storageBlocked=true;saveOkay=false;toast('Saved data needs recovery. Back up to preserve it, then restore a valid collection.')}}}catch{if(unreadableSavedState)storageBlocked=true;saveOkay=false}
function pruneSnapshots(){if(!state.records)return;const keep=new Set([...state.selected,...state.favorites,...state.shelf.flatMap(e=>e.selected)]);for(const id of Object.keys(state.records))if(!keep.has(id))delete state.records[id]}
function persist(){state.book.format='5x8';state.shelf.forEach(e=>e.book.format='5x8');pruneSnapshots();if(storageBlocked){$('#save-state').hidden=false;$('#save-state').textContent='○ Recovery needed';return}try{localStorage.setItem(KEY,JSON.stringify(state));saveOkay=true;$('#save-state').textContent='';$('#save-state').hidden=true}catch{saveOkay=false;$('#save-state').hidden=false;$('#save-state').textContent='○ Not saved';toast('Browser storage is full or unavailable. Use Back up to keep your work.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function allQuotes(){return [...state.custom,...library]}
function findQuote(id){const canonical=manifest?.aliases[id]||id;return state.custom.find(q=>q.id===id)||recordCache.get(canonical)||catalogClient?.getCached(canonical)||state.records?.[canonical]||state.records?.[id]||library.find(q=>q.id===canonical)}
function remember(q){if(q&&!q.id.startsWith('own-')){state.records=state.records||{};state.records[q.id]=q}}
async function hydrate(ids){const unique=[...new Set(ids)];for(const id of unique)remember(findQuote(id));const missing=unique.filter(id=>{const q=findQuote(id);return !q||manifest?.dateAuditVersion>=1&&!q.id.startsWith('own-')&&(q.chronology?.version!==manifest.dateAuditVersion||manifest.dateAuditId&&q.chronology?.auditId!==manifest.dateAuditId)});if(!missing.length)return;const records=await catalogClient.resolve(missing);records.forEach(q=>{if(q){recordCache.set(q.id,q);remember(q)}})}
function selectedQuotes(){return state.selected.map(findQuote).filter(Boolean)}
function importance(q){return state.ratings[q.id]??q.importance}
function yearLabel(q){return CommonplaceDates.label(q,{estimateSuffix:true})}
function titleCase(s){return s.trim()||'Commonplace Book'}
function pages(){const n=state.selected.length+2;return n+(n%2)}
function formatLabel(){return '5 × 8 in'}
function browseGroups(){
 const base=manifest?.topics||TOPICS.map(name=>({name,count:library.filter(q=>q.topics.includes(name)).length})),extra=new Map();
 state.custom.forEach(q=>q.topics.forEach(t=>extra.set(t,(extra.get(t)||0)+1)));
 return base.map(t=>{const custom=extra.get(t.name)||0,group=manifest?.browseGroups?.find(g=>g.topic===t.name);let sections=group?group.sections.slice():[];
 if(!group&&t.count+custom>(manifest?.sectionLimit||10000)&&t.count)sections.push({id:'library:'+t.name,name:'Library quotes',count:t.count});
 if((group||sections.length)&&custom)sections.push({id:'custom:'+t.name,name:'Your additions',count:custom});
 return{topic:t.name,count:t.count+custom,sections};});
}
function topicLabel(){const active=topic==='All topics'?'':section,group=browseGroups().find(g=>g.topic===topic),child=group?.sections.find(s=>s.id===active);return child?topic+' · '+child.name:topic}
function renderTopics(){const query=$('#topic-search').value.trim().toLowerCase(),total=(manifest?.total||library.length)+state.custom.length;
 const button=(parent,name,count,id='',description='')=>`<button class="topic-button ${topic===parent&&(topic==='All topics'||section===id)?'active':''}" data-topic="${esc(parent)}" data-section="${esc(id)}" title="${esc(description)}"><span>${esc(name)}</span><span>${number(count)}</span></button>`;
 const rows=browseGroups().map((g,i)=>{const matches=g.topic.toLowerCase().includes(query);if(!g.sections.length)return matches?button(g.topic,g.topic,g.count):'';
 const children=g.sections.filter(child=>matches||child.name.toLowerCase().includes(query));if(!children.length)return '';
 return `<details class="topic-group" ${topic===g.topic||query?'open':''}><summary><span>${esc(g.topic)}</span><span>${g.sections.length} sections</span></summary><div class="topic-children">${children.map(child=>button(g.topic,child.name,child.count,child.id,child.description||'')).join('')}</div></details>`;});
 $('#topic-filters').innerHTML=button('All topics','All topics',total)+rows.join('');}

function filtered(){const words=$('#search').value.trim().toLowerCase().split(/\s+/).filter(Boolean);let list=allQuotes().filter(q=>(topic==='All topics'||q.topics.includes(topic))&&(age==='all'||q.minAge<=Number(age))&&(collection==='all'||collection==='favorites'&&state.favorites.includes(q.id)||collection==='mine'&&q.id.startsWith('own-')||collection==='goodreads'&&q.popularity?.source==='Goodreads')&&words.every(w=>(q.text+' '+q.author+' '+q.topics.join(' ')+' '+q.source+' '+(q.year??'')+' '+CommonplaceDates.label(q,{sourceSuffix:false,empty:''})).toLowerCase().includes(w)));
 const sort=$('#sort').value;
 if(sort==='importance')list.sort((a,b)=>importance(b)-importance(a));
 if(sort==='author')list.sort((a,b)=>a.author.localeCompare(b.author));
 if(sort==='short')list.sort((a,b)=>a.text.length-b.text.length);
 if(sort==='oldest')list.sort((a,b)=>CommonplaceDates.sortYear(a)-CommonplaceDates.sortYear(b));
 if(sort==='likes')list.sort((a,b)=>(b.likes??-1)-(a.likes??-1));return list}
async function renderQuotes(){const serial=++querySerial,pageSize=10;$('#quote-grid').setAttribute('aria-busy','true');$('#result-count').textContent='Finding words…';try{const result=catalogClient&&manifest?await catalogClient.query({search:$('#search').value,topic,section:topic==='All topics'?'':section,age,collection,sort:$('#sort').value,page,pageSize,custom:state.custom,ratings:state.ratings,favorites:state.favorites}):(()=>{const list=filtered();return{total:list.length,page,items:list.slice((page-1)*pageSize,page*pageSize)}})();if(serial!==querySerial)return;page=result.page;const slice=result.items,totalPages=Math.max(1,Math.ceil(result.total/pageSize));slice.forEach(q=>recordCache.set(q.id,q));while(recordCache.size>220){const oldest=recordCache.keys().next().value;recordCache.delete(oldest)}$('#result-count').textContent=`${number(result.total)} found`;$('#fav-count').textContent=state.favorites.length;
 $('#active-filters').innerHTML=(topic!=='All topics'?`<button class="filter-chip" data-reset="topic">${esc(topicLabel())} ×</button>`:'')+(age!=='all'?`<button class="filter-chip" data-reset="age">Reading age ≤ ${age} ×</button>`:'');
 $('#quote-grid').innerHTML=slice.length?slice.map(q=>{const added=state.selected.includes(q.id),fav=state.favorites.includes(q.id);return `<article class="quote-card ${added?'selected':''}" data-id="${esc(q.id)}"><div class="card-top"><span class="topic-tag">${esc(topic==='All topics'?q.topics[0]:topic)}</span><button class="heart ${fav?'active':''}" data-fav="${esc(q.id)}" aria-label="${fav?'Unsave':'Save'} quote by ${esc(q.author)}" aria-pressed="${fav}">${fav?'♥':'♡'}</button></div><blockquote class="${q.text.length>190?'long':''}">“${esc(q.text)}”</blockquote><div class="author-row"><span class="author-monogram">${esc(q.author.split(/\s+/).map(s=>s[0]).slice(0,2).join(''))}</span><div class="author-details"><strong>${esc(q.author)}</strong><span>${esc(yearLabel(q))}</span></div><button class="quote-detail" data-detail="${esc(q.id)}" aria-label="Details and source for ${esc(q.author)} quote">↗</button></div><div class="card-bottom"><div><div class="card-meta">Ages ${q.minAge}+ ${q.likes!==null?'· '+number(q.likes)+' Goodreads likes'+(q.popularity?' · '+q.popularity.snapshotDate.slice(0,4):''):q.verified?'· Source checked':q.provenance?.dataset==='QuoteKG v1.2'?'· Source linked':'· Community attribution'}</div></div><button class="add-quote ${added?'added':''}" data-add="${esc(q.id)}" aria-label="${added?'Remove':'Add'} quote by ${esc(q.author)} ${added?'from':'to'} book" aria-pressed="${added}">${added?'✓':'＋'}</button></div></article>`}).join(''):`<div class="empty-results"><h3>A little more room for discovery.</h3><p>${result.message?esc(result.message):collection==='favorites'?'Save a quote with the heart to find it here.':collection==='mine'?'Bring a passage from your own reading into the collection.':'Try another word, topic, or reading age.'}</p><button class="outline" id="empty-action">${collection==='mine'?'＋ Add your first quote':'Explore all quotes ↗'}</button></div>`;
 let nums=[...new Set([1,page-1,page,page+1,totalPages])].filter(n=>n>0&&n<=totalPages).sort((a,b)=>a-b);
 $('#pagination').innerHTML=result.total>10?`<button data-page="${page-1}" ${page===1?'disabled':''} aria-label="Previous page">←</button>${nums.map((n,i)=>(i&&n-nums[i-1]>1?'<span>…</span>':'')+`<button class="${n===page?'active':''}" data-page="${n}" aria-label="Page ${n}" ${n===page?'aria-current="page"':''}>${n}</button>`).join('')}<button data-page="${page+1}" ${page===totalPages?'disabled':''} aria-label="Next page">→</button>`:'';
}catch(error){if(serial===querySerial){$('#quote-grid').innerHTML=`<div class="empty-results"><h3>The words are taking a little longer.</h3><p>${esc(error.message)}</p><button class="outline" id="retry-library">Try again ↻</button></div>`;$('#result-count').textContent='Could not load';$('#pagination').innerHTML=''}}finally{if(serial===querySerial)$('#quote-grid').setAttribute('aria-busy','false')}
}
function bookMarkup(b){return CommonplaceCoverView.markup(b)}
function renderComposer(){const quotes=state.selected.map(id=>findQuote(id)||{id,text:'Quote not loaded yet',author:'Saved reference preserved'});$('#mini-book').innerHTML=bookMarkup(state.book);$('#mini-book').className='book-mockup';$('#selected-count').textContent=`${number(quotes.length)} quote${quotes.length===1?'':'s'} collected`;$('#page-count').textContent=`${pages()} pages · ${formatLabel()}`;
 $('#selected-list').innerHTML=quotes.length?quotes.map((q,i)=>`<div class="selected-quote"><span class="selected-index">${String(i+1).padStart(2,'0')}</span><div class="selected-text"><p>${esc(q.text)}</p><span>${esc(q.author)}</span></div><div class="selected-actions"><button data-up="${esc(q.id)}" ${i===0?'disabled':''} aria-label="Move quote ${i+1} up">↑</button><button data-down="${esc(q.id)}" ${i===quotes.length-1?'disabled':''} aria-label="Move quote ${i+1} down">↓</button><button data-remove="${esc(q.id)}" aria-label="Remove quote ${i+1}">−</button></div></div>`).join(''):'';
 $('#starter').hidden=quotes.length>0;$('#shelf-count').textContent=state.shelf.length;$('#mobile-count').textContent=quotes.length+' quote'+(quotes.length===1?'':'s');
}
function render(){renderTopics();renderQuotes();renderComposer()}
function toggleQuote(id){if(state.selected.includes(id)){state.selected=state.selected.filter(x=>x!==id)}else{if(state.selected.length>=2000)return toast('This edition is limited to 2,000 quotes. Save it and begin another.');state.selected.push(id);remember(findQuote(id));toast('A thought kept. Added to your book.')}persist();renderQuotes();renderComposer()}
function showView(view){['library','shelf','about'].forEach(v=>$('#'+v+'-view').hidden=v!==view);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='shelf')renderShelf();if(view!=='library')window.scrollTo({top:0,behavior:'smooth'})}
function showModal(id){const dlg=$(id);if(!dlg.open)dlg.showModal()}
function showDetail(id){const q=findQuote(id);if(!q)return;const url=safeUrl(q.sourceUrl);$('#detail-body').innerHTML=`<blockquote class="detail-quote">“${esc(q.text)}”</blockquote><p class="detail-author">${esc(q.author)}</p><dl class="detail-metadata"><dt>Date</dt><dd>${esc(CommonplaceDates.label(q,{detailed:true}))}<br><span class="fine-print">${esc(CommonplaceDates.description(q))}</span>${CommonplaceDates.links(q).map(safeUrl).filter(Boolean).map(u=>`<br><a href="${esc(u)}" target="_blank" rel="noopener">Date reference ↗</a>`).join('')}</dd><dt>Source</dt><dd>${esc(q.source||'Personal collection')}${url?` · <a href="${esc(url)}" target="_blank" rel="noopener">Read source ↗</a>`:''}</dd><dt>Attribution</dt><dd>${q.verified?'Passage checked against the linked source text.':q.id.startsWith('own-')?'Added by you.':q.provenance?.dataset==='QuoteKG v1.2'?'Wikiquote attribution via QuoteKG; not independently verified.':'Community attribution; not independently verified.'}</dd>${provenanceHTML(q)}<dt>Suggested reading age</dt><dd>${q.minAge}+ · Editorial reading-complexity suggestion</dd><dt>Goodreads likes</dt><dd>${q.likes===null?'No recorded count for this quote.':number(q.likes)+(q.popularity?' · '+q.popularity.snapshotDate.slice(0,4)+' dataset snapshot':' · supplied by you')}${popularityHTML(q)}</dd></dl><div class="detail-actions"><button class="primary" data-detail-add="${esc(id)}">${state.selected.includes(id)?'Remove from book −':'Add to your book ＋'}</button><button class="outline" data-copy="${esc(id)}">Copy quote ↗</button></div>${q.id.startsWith('own-')?`<button class="detail-delete" data-delete="${esc(id)}">Delete my quote</button>`:''}`;showModal('#detail-dialog')}
function popularityHTML(q){const p=q.popularity;if(!p)return '';const url=safeUrl(p.sourceUrl);return `<br><span class="fine-print">Historical Goodreads count. Dataset released ${esc(p.snapshotDate)}; original observation time unknown.</span>${url?`<br><a href="${esc(url)}" target="_blank" rel="noopener">Snapshot source ↗</a>`:''}`}
function provenanceHTML(q){const p=q.provenance;if(!p)return '';if(p.dataset==='Goodreads CC0 collection')return `<dt>Archive provenance</dt><dd>Goodreads community quote · ${esc(p.snapshotDate)} dataset release<br><a href="${esc(safeUrl(p.sourceUrl))}" target="_blank" rel="noopener">Dataset source ↗</a> · <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener">Provider labels CC0</a></dd>`;if(p.dataset!=='QuoteKG v1.2')return '';const citations=(p.citations||[]).map(c=>`<p>${esc(c)}</p>`).join('');const links=(p.citationUrls||[]).map(safeUrl).filter(Boolean).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">Cited source ↗</a>`).join(' · ');const alt=(q.alternateAttributions||[]).map(a=>esc(a.author)).join(', ');return `<dt>Archive provenance</dt><dd>QuoteKG v1.2 · Wikiquote contributors<br>Imported ${esc(p.retrievedAt)} · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a></dd>${citations||links?`<dt>Citation context</dt><dd class="citation-context">${citations}${links}</dd>`:''}${alt?`<dt>Other recorded attributions</dt><dd>${alt}</dd>`:''}`}
function updateExportPreview(){$('#large-book').className='book-mockup';$('#large-book').innerHTML=bookMarkup(state.book);$('#export-summary').textContent=`${selectedQuotes().length} quotes · ${pages()} interior pages · ${formatLabel()}`;const print=CommonplacePrint.readiness(state.selected.length);$('#print-readiness').textContent=print.message;$('#download-print-pack').disabled=!print.ready;$('#title-size-value').textContent=(state.book.titleSize||28)+' pt';$('#title-fit-note').textContent='Long titles fit automatically. Words stay together.';renderColorSwatches();renderComposer();if(!$('#page-preview').hidden)renderPagePreview()}
function renderColorSwatches(){const b=CommonplaceCover.normalize(state.book),palette=CommonplaceCover.palette(b);$('#cover-swatches').innerHTML=Object.entries(CommonplaceCover.themes).map(([id,t])=>`<button type="button" class="color-swatch ${!b.coverColor&&b.theme===id?'active':''}" style="--swatch:${t.color}" data-cover-theme="${id}" title="${esc(t.label)}" aria-label="${esc(t.label)}" aria-pressed="${!b.coverColor&&b.theme===id}"><span>✓</span></button>`).join('');$('#cover-color').value=palette.background}
function openExport(){const b=CommonplaceCover.normalize(state.book);$('#book-title').value=b.title;$('#book-author').value=b.author;$('#title-font').value=b.titleFont;$('#title-size').value=b.titleSize;$('#show-sources').checked=b.sources;$('#export-status').textContent=state.selected.length?'Fonts embedded. One quotation per page. Yours to keep.':'Add at least one quote before downloading your book.';$('#page-preview').hidden=true;updateExportPreview();showModal('#export-dialog')}
function renderPagePreview(){const q=selectedQuotes()[0];$('#page-preview').innerHTML=q?`<div>“${esc(q.text)}”</div><small>${esc(q.author)}${CommonplaceDates.label(q,{empty:''})?' · '+esc(CommonplaceDates.label(q,{empty:''})):''}</small>`:'<div>Your first thought goes here.</div>'}
function renderShelf(){$('#shelf-grid').innerHTML=state.shelf.length?state.shelf.map(e=>`<article class="shelf-item"><div class="book-mockup ${esc(e.book.theme)}">${bookMarkup(e.book)}</div><h3>${esc(e.book.title)}</h3><p>${e.selected.length} quotes · saved ${esc(new Date(e.date).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}))}</p><div class="form-row"><button class="outline" data-load="${esc(e.id)}">Open edition ↗</button><button class="outline danger" data-delete-edition="${esc(e.id)}">Remove</button></div></article>`).join(''):'<div class="empty-results"><h3>Room for your first edition.</h3><p>Add quotes to your book, then choose Save to bookshelf.<br>Your editions will be waiting here.</p><button class="outline" data-view="library">Find your first words ↗</button></div>'}
function downloadJSON(){const blob=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),state,...(unreadableSavedState?{unreadableSavedState}: {})},null,2)],{type:'application/json'});downloadBlob(blob,'commonplace-collection.json');toast('Collection backed up. Keep this file somewhere safe.')}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
let fontPromise;
async function loadFont(){if(!fontPromise)fontPromise=Promise.all(['assets/book-serif.ttf','assets/book-fallback.ttf','assets/book-italic.ttf','assets/sans.ttf'].map(path=>fetch(path).then(r=>{if(!r.ok)throw Error('Could not load the book typeface.');return r.arrayBuffer()}).then(buf=>{let binary='';const bytes=new Uint8Array(buf);for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary)}))).then(([primary,fallback,italic,sans])=>({primary,fallback,italic,sans})).catch(e=>{fontPromise=null;throw e});return fontPromise}
async function exportPdf(kind,button){try{await hydrate(state.selected)}catch{return toast('Some quotes could not be loaded. Retry when your connection is restored.')}if(selectedQuotes().length!==state.selected.length)return toast('A saved quote is unavailable. Keep a backup and review the selected list.');if(!state.selected.length)return toast('Keep at least one quote before creating your book.');if(!$('#book-title').value.trim()){$('#book-title').focus();return toast('Give your book a title first.')}const label=button.innerHTML;$$('.export-actions button,.digital-downloads button').forEach(b=>b.disabled=true);button.textContent='Typesetting your edition…';$('#export-status').textContent='Preparing embedded type and your pages…';try{const font=await loadFont();const doc=window.CommonplacePDF.generate(kind,state.book,selectedQuotes(),font);const name=state.book.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'commonplace';downloadBlob(doc.output('blob'),`${name}-${kind}.pdf`);$('#export-status').textContent=`${kind==='cover'?'Full wrap cover':kind==='interior'?'Print interior':'Reading edition'} downloaded. ${kind==='cover'?'Check the spine and bleed against your printer’s template.':pages()+' interior pages, one quote per page.'}`}catch(e){$('#export-status').textContent='Could not create the PDF: '+e.message;toast('Export failed. Your book is still saved.')}finally{button.innerHTML=label;$$('.export-actions button,.digital-downloads button').forEach(b=>b.disabled=false);$('#download-print-pack').disabled=!CommonplacePrint.readiness(state.selected.length).ready}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.coverTheme){state.book.theme=d.coverTheme;delete state.book.coverColor;persist();updateExportPreview()}
 if(d.view)showView(d.view);
 if(d.close!==undefined)b.closest('dialog').close();
 if(d.topic){topic=d.topic;section=d.section||'';page=1;renderTopics();renderQuotes()}
 if(d.mode){$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#topic-filters').hidden=d.mode!=='topic';$('#topic-search').hidden=d.mode!=='topic';$('#age-filters').hidden=d.mode!=='age'}
 if(d.collection){collection=d.collection;if(collection==='goodreads')$('#sort').value='likes';page=1;$$('[data-collection]').forEach(x=>x.classList.toggle('active',x===b));renderQuotes()}
 if(d.reset){if(d.reset==='topic')topic='All topics';else{age='all';$('#age-select').value='all'}page=1;render()}
 if(d.fav){remember(findQuote(d.fav));state.favorites=state.favorites.includes(d.fav)?state.favorites.filter(x=>x!==d.fav):[...state.favorites,d.fav];persist();renderQuotes()}
 if(d.add)toggleQuote(d.add);
 if(d.remove)toggleQuote(d.remove);
 if(d.up||d.down){const id=d.up||d.down,i=state.selected.indexOf(id),j=i+(d.up?-1:1);if(j>=0&&j<state.selected.length){[state.selected[i],state.selected[j]]=[state.selected[j],state.selected[i]];persist();renderComposer()}}
 if(d.detail)showDetail(d.detail);
 if(d.detailAdd){toggleQuote(d.detailAdd);showDetail(d.detailAdd)}
 if(d.copy){const q=findQuote(d.copy);navigator.clipboard.writeText(`“${q.text}” — ${q.author}`).then(()=>toast('Quote copied.')).catch(()=>toast('Copy is unavailable in this browser. Select the text to copy it.'))}
 if(d.delete){state.custom=state.custom.filter(q=>q.id!==d.delete);state.selected=state.selected.filter(x=>x!==d.delete);state.favorites=state.favorites.filter(x=>x!==d.delete);delete state.ratings[d.delete];state.shelf.forEach(e=>e.selected=e.selected.filter(id=>id!==d.delete));persist();render();$('#detail-dialog').close();toast('Your quote was removed.')}
 if(d.page){page=Number(d.page);renderQuotes();$('#workbench').scrollIntoView({behavior:'smooth'})}
 if(d.load){const edition=state.shelf.find(x=>x.id===d.load);if(state.selected.length)state.shelf.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),book:{...state.book},selected:[...state.selected]});state.book={...edition.book};state.selected=[...edition.selected];persist();render();hydrate(state.selected).then(()=>{persist();renderComposer()}).catch(()=>toast('Some saved quotes could not be loaded. Your edition is preserved.'));showView('library');toast('Edition opened. Your previous draft was saved to the bookshelf.')}
 if(d.deleteEdition){state.shelf=state.shelf.filter(x=>x.id!==d.deleteEdition);persist();renderShelf();renderComposer();toast('Edition removed from the bookshelf.')}
 if(b.id==='retry-library'){initializeLibrary()}
 if(b.id==='empty-action'){if(collection==='mine')showModal('#quote-dialog');else{topic='All topics';age='all';collection='all';page=1;$('#age-select').value='all';$('#search').value='';$$('[data-collection]').forEach(x=>x.classList.toggle('active',x.dataset.collection==='all'));render()}}
});
$('#add-own-top').addEventListener('click',()=>showModal('#quote-dialog'));
$('#own-topic').innerHTML=TOPICS.map(t=>`<option>${esc(t)}</option>`).join('');
$('#quote-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),year=f.get('year'),likes=f.get('likes');const q={id:'own-'+crypto.randomUUID(),text:f.get('text').trim(),author:f.get('author').trim(),year:year===''?null:Number(year),topics:[f.get('topic')],minAge:Number(f.get('minAge')),importance:3,likes:likes===''?null:Number(likes),source:f.get('source').trim()||'Personal collection',sourceUrl:safeUrl(f.get('sourceUrl')),verified:false,authorInfo:''};if(!validateQuote(q))return toast('Please check your quote, author, and numeric values.');state.custom.unshift(q);persist();topic='All topics';age='all';$('#age-select').value='all';collection='mine';page=1;$('#search').value='';$$('[data-collection]').forEach(x=>x.classList.toggle('active',x.dataset.collection==='mine'));render();$('#quote-dialog').close();e.target.reset();showView('library');toast('Your words are now part of the library.')});
let searchTimer;$('#search').addEventListener('input',()=>{page=1;++querySerial;clearTimeout(searchTimer);searchTimer=setTimeout(renderQuotes,180)});$('#sort').addEventListener('change',()=>{page=1;renderQuotes()});$('#age-select').addEventListener('change',e=>{age=e.target.value;page=1;renderQuotes()});$('#reset-age').addEventListener('click',()=>{age='all';$('#age-select').value='all';page=1;renderQuotes()});
$('#starter').addEventListener('click',()=>{state.selected=library.slice(0,6).map(q=>q.id);library.slice(0,6).forEach(remember);persist();renderQuotes();renderComposer();toast('Six thoughts to begin your collection.')});
$('#create-book').addEventListener('click',openExport);$('#edit-book').addEventListener('click',openExport);
$('#save-edition').addEventListener('click',()=>{if(!state.selected.length)return toast('Add a quote before saving an edition.');if(state.shelf.length>=200)return toast('Your shelf has 200 editions. Back up or remove one first.');state.shelf.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),book:{...state.book},selected:[...state.selected]});persist();renderComposer();toast('An edition saved to your bookshelf.')});
$('#new-book').addEventListener('click',()=>{if(state.selected.length){state.shelf.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),book:{...state.book},selected:[...state.selected]})}state.selected=[];state.book={title:'Commonplace Book',author:'',format:'5x8',theme:'forest',sources:true};persist();render();showView('library');toast('A fresh page. Your previous book is on the shelf.')});
$('#backup').addEventListener('click',downloadJSON);$('#restore').addEventListener('click',()=>$('#restore-file').click());
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000000)throw Error('This backup exceeds the 100 MB import limit.');const backup=JSON.parse(await file.text());if(backup.version!==1||!validateState(backup.state))throw Error('This is not a valid Commonplace backup.');const incoming=backup.state;const personal=new Set(incoming.custom.map(q=>q.id));const refs=[...new Set([...incoming.selected,...incoming.favorites,...incoming.shelf.flatMap(s=>s.selected)])].filter(id=>!personal.has(id)&&!incoming.records?.[id]);const missing=refs.length?(catalogClient?await catalogClient.hasIds(refs):refs.filter(id=>!findQuote(id))):[];if(missing.length)throw Error('This backup references quotes that are missing.');incoming.records=incoming.records||{};const toLoad=incoming.selected.filter(id=>!personal.has(id)&&!incoming.records[id]);const loaded=toLoad.length?(catalogClient?await catalogClient.resolve(toLoad):toLoad.map(findQuote)):[];loaded.filter(Boolean).forEach(q=>incoming.records[q.id]=q);downloadJSON();state=incoming;storageBlocked=false;unreadableSavedState=null;migrateAliases();state.selected=[...new Set(state.selected)];state.favorites=[...new Set(state.favorites)];persist();render();toast('Collection restored. A backup of the previous collection was downloaded.')}catch(err){toast(err.message)}finally{e.target.value=''}});
const bookInputs={'book-title':'title','book-author':'author','title-font':'titleFont','title-size':'titleSize','show-sources':'sources'};
Object.entries(bookInputs).forEach(([id,key])=>$('#'+id).addEventListener('input',e=>{state.book[key]=e.target.type==='checkbox'?e.target.checked:key==='titleSize'?Number(e.target.value):e.target.value;if(key==='title'&&!state.book.title.trim())state.book.title='Commonplace Book';persist();updateExportPreview()}));
$('#preview-page').addEventListener('click',()=>{$('#page-preview').hidden=!$('#page-preview').hidden;renderPagePreview()});
['reading','interior','cover'].forEach(kind=>$('#download-'+kind).addEventListener('click',e=>exportPdf(kind,e.currentTarget)));
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$$('dialog').some(d=>d.open)){e.preventDefault();showView('library');$('#search').focus()}});
function migrateAliases(){if(!manifest)return;const canonical=id=>manifest.aliases[id]||id;state.selected=[...new Set(state.selected.map(canonical))];state.favorites=[...new Set(state.favorites.map(canonical))];state.shelf.forEach(e=>e.selected=[...new Set(e.selected.map(canonical))]);for(const [id,rating] of Object.entries(state.ratings)){const key=canonical(id);if(key!==id){if(state.ratings[key]===undefined)state.ratings[key]=rating;delete state.ratings[id]}}if(state.records)for(const [id,q] of Object.entries(state.records)){const key=canonical(id);if(key!==id){state.records[key]={...q,id:key};delete state.records[id]}}}
async function initializeLibrary(){try{if(!catalogClient)catalogClient=new window.CommonplaceLibrary({base:'data/'});manifest=await catalogClient.init();archiveAuthors=new Set(manifest.authorNames||[]);library=manifest.initial;library.forEach(q=>recordCache.set(q.id,q));migrateAliases();render();try{await hydrate(state.selected);persist();renderComposer()}catch{toast('Some saved quotes could not be loaded. Your edition is preserved; the library is ready to browse.')}}catch(error){$('#quote-grid').innerHTML=`<div class="empty-results"><h3>The library could not be opened.</h3><p>${esc(error.message)} Your saved collection is preserved.</p><button class="outline" id="retry-library">Try again ↻</button></div>`;renderComposer()}}
if(typeof window!=='undefined'&&typeof window.CommonplaceLibrary==='function')initializeLibrary();


$('#mobile-book-jump').addEventListener('click',()=>{showView('library');$('#book-composer').scrollIntoView({behavior:'smooth'})});

$('#topic-search').addEventListener('input',renderTopics);

$('#cover-color').addEventListener('input',e=>{state.book.coverColor=e.target.value;persist();updateExportPreview()});
$('#upload-cover').addEventListener('click',()=>$('#cover-file').click());
$('#cover-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;$('#cover-image-status').textContent='Preparing your image…';try{const data=await CommonplaceCoverView.prepareImage(file);state.book.coverImage=data;persist();updateExportPreview();$('#cover-image-status').textContent=saveOkay?'Image added to your cover.':'Image added. Back up your book to keep it.'}catch(err){$('#cover-image-status').textContent=err.message}finally{e.target.value=''}});
$('#reset-cover').addEventListener('click',()=>{delete state.book.coverImage;persist();updateExportPreview();$('#cover-image-status').textContent='Original engraving restored.'});
if(document.fonts?.ready)document.fonts.ready.then(()=>{renderComposer();if($('#export-dialog').open)updateExportPreview()});

$('#download-print-pack').addEventListener('click',async e=>{const button=e.currentTarget,label=button.innerHTML,ids=[...state.selected],book={...state.book,printProfile:'lulu'},print=CommonplacePrint.readiness(ids.length);if(!print.ready)return toast(print.message);button.disabled=true;button.textContent='Preparing your print files…';$('#export-status').textContent='Typesetting your interior and cover…';try{await hydrate(ids);const quotes=ids.map(findQuote).filter(Boolean);if(quotes.length!==ids.length)throw Error('A saved quote is unavailable. Your book is still saved.');const font=await loadFont(),interior=CommonplacePDF.generate('interior',book,quotes,font),cover=CommonplacePDF.generate('cover',book,quotes,font),zip=CommonplacePrint.zip([{name:'01-interior.pdf',data:new Uint8Array(interior.output('arraybuffer'))},{name:'02-cover.pdf',data:new Uint8Array(cover.output('arraybuffer'))},{name:'START-HERE.txt',data:CommonplacePrint.instructions(book,print.pages)}]),name=book.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'commonplace';downloadBlob(new Blob([zip],{type:'application/zip'}),name+'-print-files.zip');$('#export-status').textContent='Print files downloaded. Unzip the folder, then open Lulu and upload 01-interior.pdf and 02-cover.pdf. Review the preview, enter your address, and check out.'}catch(err){$('#export-status').textContent='Could not prepare print files: '+err.message}finally{button.innerHTML=label;button.disabled=!CommonplacePrint.readiness(state.selected.length).ready}});
